const {chromium}=require('playwright');
const assert=require('assert');
const base=process.env.KFX_BASE_URL||'http://127.0.0.1:8080/test.html';
const banned=[/prototype/i,/production system/i,/production engine/i,/product[- ]intelligence note/i,/future commerce opportunity/i,/support role still/i,/second support role/i,/role being completed/i,/current story/i,/eligible after product verification/i,/automatically escalating merchandise/i,/treatment value,? not filler/i,/implementation sheets/i,/separate solution/i];
(async()=>{const browser=await chromium.launch({headless:true});const failures=[];for(const vp of [{width:390,height:844,name:'phone'},{width:1280,height:900,name:'desktop'}]){const page=await browser.newPage({viewport:vp});try{await page.goto(base,{waitUntil:'domcontentloaded',timeout:30000});await page.waitForSelector('#opening');await page.waitForTimeout(500);let intro=await page.evaluate(()=>({title:document.title,eyebrow:document.querySelector('#intro .hero .eyebrow')?.textContent||'',audit:window.KFX047VisibleAudit?window.KFX047VisibleAudit():null}));assert(!/prototype/i.test(intro.eyebrow),'intro exposes prototype language');assert(intro.audit&&intro.audit.pass,'intro visible-language audit failed '+JSON.stringify(intro.audit));await page.evaluate(()=>{state.opening='My right wrist and thumb hurt after phone and computer use for four weeks. No injury.';document.querySelector('#intro')?.classList.add('hidden');document.querySelector('#chatView')?.classList.add('hidden');document.querySelector('#solutionView')?.classList.remove('hidden');if(window.KFX047VisibleAudit)window.KFX047VisibleAudit();});await page.waitForTimeout(500);const main=await page.evaluate(()=>{const text=(document.querySelector('#solutionView')?.innerText||'').replace(/\s+/g,' ');const audit=window.KFX047VisibleAudit?window.KFX047VisibleAudit():null;const imgs=[...document.querySelectorAll('#solutionView img')].filter(x=>x.getClientRects().length).map(x=>({w:x.getBoundingClientRect().width,h:x.getBoundingClientRect().height}));return{text,audit,imgs,packet:!!document.querySelector('#kfxVPacketBtn')};});assert(main.audit&&main.audit.pass,'solution language audit failed '+JSON.stringify(main.audit));assert(/Here’s what Keneflex recommends/i.test(main.text),'recommendation headline not consumer-facing');assert(/Something about this plan doesn't work for me/i.test(main.text),'plan adjustment CTA remains vague');assert(!/care packet|included value|second support role|support role still/i.test(main.text),'legacy/internal plan wording still visible');assert(main.imgs.some(x=>x.w>=60&&x.h>=60),'product imagery is too small or absent');assert(main.packet,'Keneflex Plan button missing');const popupPromise=page.waitForEvent('popup');await page.click('#kfxVPacketBtn');const pop=await popupPromise;await pop.waitForLoadState('domcontentloaded');await pop.waitForTimeout(200);const plan=await pop.evaluate(()=>({title:document.title,text:(document.body.innerText||'').replace(/\s+/g,' '),svgs:document.querySelectorAll('svg').length,imgs:document.querySelectorAll('img').length,sections:['support','movement','recovery','activity','setup','followup'].filter(id=>document.getElementById(id)).length,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+2}));assert.equal(plan.title,'Your Keneflex Plan');for(const rx of banned)assert(!rx.test(plan.text),'plan leaks internal language: '+rx);assert(!/\$0|care packet|choose the sheets/i.test(plan.text),'plan devalues guidance or creates sheet-selection burden');assert(plan.svgs>=5,'visual plan lacks enough explanatory visuals');assert(plan.imgs>=1,'selected product image absent from plan');assert(plan.sections>=6,'not all relevant plan sections rendered');assert(!plan.overflow,'plan horizontally overflows '+vp.name+' viewport');await pop.close();console.log('PASS 0.4.7 full-page '+vp.name);}catch(e){failures.push({viewport:vp.name,error:e.message});console.error('FAIL 0.4.7 '+vp.name,e.message)}await page.close()}await browser.close();console.log(JSON.stringify({viewports:2,failures},null,2));if(failures.length)process.exit(1)})();
